<script lang="ts">
 import {onMount} from 'svelte';
 import {Button} from '$lib/components/ui/button';
 import {LoaderCircle,RefreshCw} from '@lucide/svelte';
 import {request} from './api';
 let days=$state('28'),data=$state<any>(null),loading=$state(true),error=$state('');let sequence=0;
 const number=(value:number|null|undefined)=>value==null?'—':value.toLocaleString();
 const percent=(value:number|null|undefined)=>value==null?'—':`${value.toFixed(1)}%`;
 async function load(){const current=++sequence;loading=true;error='';try{const result=await request(`/creator/analytics/detail?days=${days}`);if(current===sequence)data=result;}catch(e){if(current===sequence)error=(e as Error).message;}finally{if(current===sequence)loading=false;}}
 onMount(()=>{void load();return()=>{sequence++;};});
</script>
<section class="creator-analytics" aria-labelledby="analytics-title"><div class="analytics-heading"><div><h2 id="analytics-title">Audience overview</h2><p>Accepted watch activity from signed-in viewers. Counts can differ from page visits.</p></div><div class="analytics-controls"><label class="sr-only" for="analytics-range">Analytics date range</label><select id="analytics-range" bind:value={days} onchange={()=>load()} disabled={loading}><option value="7">Last 7 days</option><option value="28">Last 28 days</option><option value="90">Last 90 days</option></select><Button variant="ghost" size="icon" aria-label="Refresh analytics" disabled={loading} onclick={load}><RefreshCw class="size-4"/></Button></div></div>
{#if error}<div role="alert" class="cloud-alert">{error}<Button variant="ghost" onclick={load}>Try again</Button></div>{/if}
{#if loading&&!data}<p class="analytics-loading" role="status"><LoaderCircle class="size-4 animate-spin"/>Loading audience activity…</p>{:else if data}<div class="analytics-totals" aria-busy={loading}>{#each [{label:'Qualified views',value:number(data.qualified_views)},{label:'Watch minutes',value:number(Math.round(data.watch_seconds/60))},{label:'Watch sessions',value:number(data.sessions)},{label:'Unique viewers',value:number(data.unique_viewers)}] as metric}<div><span>{metric.label}</span><strong>{metric.value}</strong></div>{/each}</div><p class="analytics-note">Views qualify after accepted watch time and are deduplicated per viewer, video and UTC day. Unique viewers and engagement rates appear only with at least {data.privacy_minimum} viewers.</p>
<details class="analytics-daily"><summary>Daily activity</summary><div class="analytics-table-wrap"><table><thead><tr><th scope="col">Date · UTC</th><th scope="col">Qualified views</th><th scope="col">Watch minutes</th></tr></thead><tbody>{#each data.daily as day}<tr><th scope="row">{day.date}</th><td>{number(day.qualified_views)}</td><td>{number(Math.round(day.watch_seconds/60))}</td></tr>{/each}</tbody></table></div></details>
<div class="analytics-videos-heading"><h3>Video performance</h3><p>Up to 50 videos, ordered by qualified views in this period.</p></div>{#if data.videos.length}<div class="analytics-table-wrap"><table><thead><tr><th scope="col">Video</th><th scope="col">Qualified views</th><th scope="col">Watch minutes</th><th scope="col">Unique viewers</th><th scope="col">Watch-through</th></tr></thead><tbody>{#each data.videos as video}<tr><th scope="row"><a href={`/watch/${video.id}`}>{video.title}</a><small>{video.format==='short'?'Short':'Video'}</small>{#if video.watch_reach_25_percent!=null}<details class="analytics-reach"><summary>Watch time reach</summary><span>25%: {percent(video.watch_reach_25_percent)} · 50%: {percent(video.watch_reach_50_percent)} · 75%: {percent(video.watch_reach_75_percent)} · Full duration: {percent(video.watch_reach_100_percent)}</span></details>{/if}</th><td>{number(video.qualified_views)}</td><td>{number(Math.round(video.watch_seconds/60))}</td><td>{number(video.unique_viewers)}</td><td>{percent(video.completion_percent)}</td></tr>{/each}</tbody></table></div>{:else}<p class="analytics-empty">Publish your first video to start seeing its performance here.</p>{/if}
<p class="analytics-note">Watch-through estimates sessions with accepted watch time of at least 90% of a measured video’s duration. Replays can contribute; this is an engagement estimate, not frame-by-frame retention. It does not calculate payouts.</p><p class="analytics-freshness">Updated {new Date(data.generated_at).toLocaleString()} · UTC date boundaries · {loading?'Refreshing…':'Live database totals'}</p>{/if}</section>
<style>.creator-analytics{padding:8px 0 32px;min-width:0}.analytics-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.analytics-heading h2{font-size:19px;font-weight:600}.analytics-heading p,.analytics-videos-heading p{font-size:12px;line-height:1.7;color:var(--muted-foreground);margin-top:7px}.analytics-controls{display:flex;gap:6px;align-items:center;flex-shrink:0}.analytics-controls select{min-height:36px;padding:6px 10px;background:var(--background);border:1px solid var(--border);border-radius:var(--radius);font-size:12px}.analytics-controls select:focus-visible,summary:focus-visible,a:focus-visible{outline:2px solid var(--ring);outline-offset:3px}.analytics-totals{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;padding:28px 0 20px}.analytics-totals span{display:block;font-size:12px;color:var(--muted-foreground)}.analytics-totals strong{font-size:27px;letter-spacing:-.02em;font-weight:600;display:block;margin-top:7px;font-variant-numeric:tabular-nums}.analytics-note,.analytics-freshness{font-size:12px;color:var(--muted-foreground);line-height:1.8;max-width:85ch}.analytics-freshness{margin-top:16px}.analytics-daily{margin:22px 0;border-block:1px solid var(--border);padding:15px 0}.analytics-daily>summary{cursor:pointer;font-size:13px;font-weight:500}.analytics-videos-heading{margin:26px 0 12px}.analytics-videos-heading h3{font-size:15px;font-weight:600}.analytics-table-wrap{overflow-x:auto;margin:12px 0 18px}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}th,td{padding:13px 12px;border-bottom:1px solid var(--border);vertical-align:top}thead th{font-weight:500;color:var(--muted-foreground);white-space:nowrap}tbody th{font-weight:500;min-width:180px;max-width:360px}tbody th a{overflow-wrap:anywhere}th small{display:block;color:var(--muted-foreground);font-size:11px;margin-top:5px;font-weight:400}td{font-variant-numeric:tabular-nums;white-space:nowrap}.analytics-reach{font-size:11px;color:var(--muted-foreground);margin-top:9px;font-weight:400}.analytics-reach summary{cursor:pointer}.analytics-reach span{display:block;margin-top:6px;line-height:1.7}.analytics-loading{display:flex;gap:9px;align-items:center;padding:28px 0;font-size:13px;color:var(--muted-foreground)}.analytics-empty{padding:20px 0;font-size:13px;color:var(--muted-foreground)}@media(max-width:650px){.analytics-heading{flex-direction:column;gap:14px}.analytics-totals{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.analytics-totals strong{font-size:24px}th,td{padding-inline:9px}}</style>
